const CLOUD_SPEC={
  classic:[{n:5,r:46,a:0.55,spd:0.18},{n:4,r:82,a:0.85,spd:0.42},{n:2,r:140,a:0.92,spd:1.05}],
  cel:    [{n:5,r:46,a:0.8, spd:0.18},{n:4,r:82,a:0.95,spd:0.42},{n:2,r:140,a:1,   spd:1.05}]};
