function fireball(x,y,r,a){ if(a<=0||r<=1) return; const ga=ctx.globalAlpha; ctx.globalAlpha=ga*clamp(a,0,1); blit(FIRE_SPR,x,y,r); ctx.globalAlpha=ga; }
